(function ($, Drupal, cookies) {
  Drupal.behaviors.cookieBlock = {
    attach: function (context) {

      $('body', context).once('cookieBlockBehavior').each(function () {

        // Remove cookie.
        // cookies.remove('cutest');

        let cookie_name = 'Drupal.visitor.cookiepolitic';
        let cookie_current = cookies.get(cookie_name);
        let cookie_block = $('#block-cookie-form');

        if (typeof cookie_current === 'undefined' ) {
          cookie_block.addClass('active');

          $('#block-cookie-form-button').on('click', function() {
            cookies.set(cookie_name, 1);
            cookie_block.removeClass('active');
          });

        }

      });

    }
  };
})(jQuery, Drupal, window.Cookies);
