(function ($, Drupal, drupalSettings) {
  'use strict';

  // Добавляет SKU в корзину.
  Drupal.addToCartSKU = function addToCartSKU(sku, quantity = 1) {
    $.ajax({
      url: Drupal.url('add-to-cart-sku'),
      type: 'POST',
      beforeSend: function(xhr) {
        xhr.setRequestHeader('X-CSRF-TOKEN', drupalSettings.AddToCartSkuCsrfToken);
      },
      data: {
        sku: sku,
        quantity: quantity,
      },
      error: response => {
        console.error({message: 'Error into ajax (/add-to-cart-sku)', response: response});
      },
    });
  };

})(jQuery, Drupal, drupalSettings);
