'use strict';

(function ($) {
  Drupal.behaviors.buttons = {
    attach: function attach(context, settings) {
      var btnToggle = $('.btn-toggle');

      btnToggle.on('click', function () {
        $(this).toggleClass('active');
      });
    }
  };
})(jQuery);;
'use strict';

(function ($) {
  Drupal.behaviors.headerheight = {
    attach: function attach(context, settings) {
      if (once('headerheight', 'body').lenght === 0) {
        return;
      }

      // Fixed menu for scrolling page.
      let header = $('#head');
      let body = $('body');
      let headerTopHeight = $('.header__top').height();
      let scrolled = "scrolled";
      const is_promotion_page = $('.promotion-page').length > 0;

      $(window).scroll(function () {
        header[$(this).scrollTop() > headerTopHeight ? 'addClass' : 'removeClass'](scrolled);
        if (is_promotion_page) {
          body[$(this).scrollTop() > headerTopHeight ? 'addClass' : 'removeClass'](scrolled);
        }
      });

      // Resize Init
      $(window).resize(function () {
        headerHeight();
      });

      // Disable fixed menu for mobile device.
      function headerHeight() {
        let currentWindowWidth = $(window).width();
        let headerWrapper = $('.header');

        if (currentWindowWidth >= 640) {
          let headerHeight = header.height();
          setTimeout(function () {
            headerWrapper.css('minHeight', headerHeight + headerTopHeight);
          }, 0);

        } else {
          headerWrapper.css('minHeight', 'auto');
        }
      }

      // First Init.
      headerHeight();

      // if (currentWindowWidth < 640) {
      //   let headerWrapper = $('.header');
      //   headerWrapper.css('minHeight', 116);
      // }

    }
  };

  Drupal.behaviors.citySwitcher = {
    attach: function attach(context, settings) {
      $('.header__location', context).once('choseCity').each(function () {
        var parent = $(this),
            confirm = parent.find('.region-switcher__confirm'),
            switcher = parent.find('.header__location-switcher'),
            switcherChange = parent.find('.region-switcher__change'),
            headerLocationChange = parent.find('.header__location-link');

        confirm.on('click', function () {
          var city = switcher.data('city');
          var region = switcher.data('region');
          $.cookie('hua-city', city, { expire: '', domain: '', path: '/' });
          $.cookie('hua-region', region, { expire: '', domain: '', path: '/' });

          switcher.hide(100);
          setStorageNameSupported();
        });

        if (!$.cookie('currentLocation.popup')) {
          switcher.show();
        }

        switcherChange.on('click', function () {
          switcher.hide(100);
          setStorageNameSupported();
          $('.header__location-link').click();
        });
        headerLocationChange.on('click', function () {
          switcher.hide(100);
          setStorageNameSupported();
        });
        function setStorageNameSupported() {
          $.cookie("currentLocation.popup", 1, { expire: '', domain: '', path: '/' });
        }
      });
    }
  };

  Drupal.behaviors.addToCartMessage = {
    attach: function attach(context, settings) {
      $('.page-overlay').click(function () {
        $('.header__cart-notification').fadeOut(300);
        $('.page-overlay').fadeOut(300);
      });

      $('body').once().on('click', '.header__messages-close', function () {
        $('.header__cart-notification').fadeOut(300);
        $('.page-overlay').fadeOut(300);
      });
    }
  };
})(jQuery);
;
'use strict';

(function ($) {
  Drupal.behaviors.huaMessageBehavior = {
    attach: function attach(context, settings) {

      /*Message*/
      if ($('.messages__item-close').length > 0) {
        $('.messages__item-close').on('click', function () {
          $(this).parents('.messages__item').fadeOut(300);
        });
        if (settings.user.role != 'administrator') {
          setTimeout(function () {
            $('.messages__item-close').click();
          }, 5000);
        }
      }
      /*Message*/
    }
  };
})(jQuery);;
(function ($) {

  // Search
  $('.header__search').click(function(){
    openSearch();
  });

  $('.js-page-404-search-trigger').on('click', function () {
    var headerSearch = document.querySelector('.header__search');
    if (headerSearch) {
      headerSearch.click();
    }
  });

  $('.header__search-form-close').on('click', function () {
    closeSearch();
  });

  // Open search
  function openSearch(){
    $('.header__search').closest('.header__icon').addClass('active');
    $('.header__search-form').addClass('active');
    setTimeout(function(){
      var searchInput = $('.header__search-form input[type="text"]')[0];
      if (searchInput) {
        searchInput.focus();
      }
    }, 100);
  }

  // Close search
  function closeSearch(){
    $('.header__search').closest('.header__icon').removeClass('active');
    $('.header__search-form').removeClass('active');
  }


})(jQuery, Drupal, drupalSettings);
