(function ($) {
  Drupal.Ajax.prototype.setProgressIndicatorFullscreen = function () {
    this.progress.element = $(Drupal.theme('ajaxProgressIndicatorFullscreen'));
    $('.catalog__grid').append(this.progress.element);
  };

  Drupal.Ajax.prototype.setProgressIndicatorThrobber = function () {
    if ($(this.element).closest('.product-teaser').length) {
      this.progress.element = $(Drupal.theme('ajaxProgressThrobber'));
      $(this.element).closest('.product-teaser').append(this.progress.element);
    } else if ($(this.element).closest('.good-page__memory-list').length) {
      this.progress.element = $(Drupal.theme('ajaxProgressThrobber'));
      $(this.element).closest('.form-item__radios').append(this.progress.element);
    } else if ($(this.element).closest('.good-page__colors-list').length) {
      this.progress.element = $(Drupal.theme('ajaxProgressThrobber'));
      $(this.element).closest('.form-item__radios').append(this.progress.element);
    } else if ($(this.element).closest('.form-panel').length) {
      this.progress.element = $(Drupal.theme('ajaxProgressThrobber'));
      $(this.element).closest('.form-item').append(this.progress.element);
    } else {
      this.progress.element = $(Drupal.theme('ajaxProgressThrobber'));
      $(this.element).after(this.progress.element);
    }
  };

  Drupal.theme.ajaxProgressThrobber = function (message) {
    var messageMarkup = typeof message === 'string' ? Drupal.theme('ajaxProgressMessage', message) : '';
    var throbber = '<div class="throbber">&nbsp;</div>';

    return '<div class="ajax-progress ajax-progress-throbber">' + throbber + messageMarkup + '</div>';
  };
})(jQuery);;
'use strict';

(function ($, Drupal) {
  Drupal.behaviors.mobileBehavior = {
    attach: function(context, settings) {

      // Generate and events mobile elements.
      class MobileElements {

        // Header menu.
        headerMobileMenu() {

          let itemsHeaderMenu = $('.header__menu .nav-main__row > .nav-main__item');
          let itemsHeaderMenuTemplate = '';

          for (let i = 0; i < itemsHeaderMenu.length; i++) {

            let parentItem = $(itemsHeaderMenu[i]).find('.nav-main__link-parent').html();
            let childrenItems = $(itemsHeaderMenu[i]).find('.nav-main__group');

            // If children items.
            let isChildrenItems = '';
            if (childrenItems.length > 0) {
              isChildrenItems = 'is_children';
            }

            itemsHeaderMenuTemplate += '<li class="mobile-menu__item ' + isChildrenItems + '">';

            // Parent link.
            itemsHeaderMenuTemplate += '<div class="mobile-menu__item-name">' + parentItem + '</div>';

            // Children links.
            if (childrenItems.length > 0) {

              itemsHeaderMenuTemplate += '<div class="mobile-menu__item-drops">';

              for (let c = 0; c < childrenItems.length; c++ ) {

                let childrenTitle = $(childrenItems[c]).find('.nav-main__header').html();
                let childrenItemsLinks = $(childrenItems[c]).find('.nav-main__link-list li');

                itemsHeaderMenuTemplate += '<div class="mobile-menu__item-drop">';

                // Children title.
                itemsHeaderMenuTemplate += '<div class="mobile-menu__item-name">' + childrenTitle + '</div>';

                // Children items.
                itemsHeaderMenuTemplate += '<div class="mobile-menu__item-drop-items">';
                itemsHeaderMenuTemplate += '<ul>';

                for (let b = 0; b < childrenItemsLinks.length; b++) {

                  let childItem = $(childrenItemsLinks[b]).find('a');
                  let childItemTitle = childItem.text();
                  let childItemHref = childItem.attr('href');
                  let childItemClass = childItem.attr('class') || '';
                  let childItemClassAttribute = childItemClass ? ' class="' + childItemClass + '"' : '';

                  itemsHeaderMenuTemplate += '<li><a href="' + childItemHref + '"' + childItemClassAttribute + '>' + childItemTitle + '</a></li>';

                }
                itemsHeaderMenuTemplate += '</ul>';
                itemsHeaderMenuTemplate += '</div>';

                itemsHeaderMenuTemplate += '</div>';
              }

              itemsHeaderMenuTemplate += '</div>';

            }

            itemsHeaderMenuTemplate += '</li>'

          }

          return itemsHeaderMenuTemplate;

        }

        // Top header menu.
        topHeaderMobileMenu() {

          let itemsTopHeaderMenu = $('.header__top-menu li');
          let itemsTopHeaderMenuTemplate = '';

          for (let i = 0; i < itemsTopHeaderMenu.length; i++) {

            let itemTopHeader = $(itemsTopHeaderMenu[i]).find('a');
            let itemTopHeaderTitle = itemTopHeader.text();
            let itemTopHeaderHref = itemTopHeader.attr('href');

            itemsTopHeaderMenuTemplate += '<li class="mobile-menu__item-top">';
            itemsTopHeaderMenuTemplate += '<a href="' + itemTopHeaderHref + '">' + itemTopHeaderTitle + '</a>';
            itemsTopHeaderMenuTemplate += '</li>';

          }

          return itemsTopHeaderMenuTemplate;

        }

        // Top header info.
        topHeaderMobileInfo() {

          let infoWork = $('.header__phone-note').text();
          let infoPhone = $('.header__phone-link').text();

          let topMobileInfoTemplate = '<div class="mobile-menu__item-info work">' + infoWork + '</div>';
          topMobileInfoTemplate += '<div class="mobile-menu__item-info phone"><a href="tel:' + infoPhone + '">' + infoPhone + '</a></div>';

          return topMobileInfoTemplate;

        }

        // User mobile menu.
        userMobileMenu() {

          let currentPath = window.location.pathname;
          let activeHome = '';
          let activeCatalog = '';
          let activeFavorite = '';
          let activeProfile = '';
          let activeCartOrCheckout = '';

          let userMobileMenuTemplate = '';

          // Home.
          if(currentPath === '/') {
            activeHome = 'active';
          }
          userMobileMenuTemplate += '<a href="/" class="bottom_menu_item menu_home ' + activeHome + '"><span>Главная</span></a>';

          // Catalog.
          if (currentPath.indexOf('/catalog/') > -1 || currentPath.indexOf('/product/') > -1) {
            activeCatalog = 'active';
          }
          userMobileMenuTemplate += '<a href="" class="bottom_menu_item menu_catalog ' + activeCatalog + '"><span>Каталог</span></a>';

          // Favorite.
          let header_favorites = $(".header__favorites");
          let favoriteHref = '/user/login';
          let favoriteClass = 'hide';

          if(header_favorites.length > 0) {
            favoriteHref = $(".header__favorites").attr('href');
          }

          let favoriteCount = header_favorites.find('.header__count-value').text();
          if (header_favorites.find('.header__count-value').length > 0) {
            favoriteCount = $('.header__favorites .header__count-value').text();
            favoriteCount = Number(favoriteCount);
          }

          if (favoriteCount > 0) {
            favoriteClass = '';
          }

          if (currentPath.indexOf('/favorite') > -1) {
            activeFavorite = 'active';
          }
          userMobileMenuTemplate += '<a href="' + favoriteHref + '" class="bottom_menu_item menu_favorite header__favorites ' + activeFavorite +'">';
          userMobileMenuTemplate += '<div class="header__count ' + favoriteClass + '">';
          userMobileMenuTemplate += '<span class="header__count-value">' + favoriteCount + '</span>';
          userMobileMenuTemplate += '</div>';
          userMobileMenuTemplate += '<span>Избранное</span>';
          userMobileMenuTemplate += '</a>';

          // Profile.
          let userText = 'Войти';
          let userIsAuth = '';
          if ($('.nav-advanced__popup').length > 0) {
            userText = 'Профиль';
            userIsAuth = 'is_auth';
          }

          if (currentPath.indexOf('/user') > -1 && currentPath.indexOf('/favorite') < 0) {
            activeProfile = 'active';
          }
          userMobileMenuTemplate += '<a href="/user/login" class="bottom_menu_item menu_profile ' + userIsAuth + ' ' + activeProfile + '"><span>' + userText + '</span></a>';

          // Cart.
          let cartCount = 0;
          let cartIsCount = 'hide';
          let cartCountElement = $('.header__cart .header__count-value');

          // Count in cart.
          if (cartCountElement.length > 0) {
            cartCount = cartCountElement.text();
            cartIsCount = '';
          }

          // Active page cart.
          if (currentPath.indexOf('/cart') > -1 || currentPath.indexOf('/checkout') > -1) {
            activeCartOrCheckout = 'active';
          }

          userMobileMenuTemplate += '<a href="/cart" class="bottom_menu_item menu_cart ' + activeCartOrCheckout + '">';
          userMobileMenuTemplate += '<div class="header__count ' + cartIsCount + '">';
          userMobileMenuTemplate += '<span class="header__count-value">' + cartCount + '</span>';
          userMobileMenuTemplate += '</div>';
          userMobileMenuTemplate += '<span>Корзина</span></a>'

          return userMobileMenuTemplate;

        }

        // Footer menu event.
        footerMobileMenu() {

          let fooTitle = $('.footer__title');
          fooTitle.unbind('click');

          fooTitle.on('click', function() {
            let wrapFootMenu = $(this).parent('.footer__col');
            if (wrapFootMenu.hasClass('active')) {
              wrapFootMenu.removeClass('active');
            } else {
              wrapFootMenu.addClass('active');
            }
          });

        }

        // Breadcrumb catalog.
        breadcrumbInit () {
          let breadcrumbs = $('.breadcrumbs');
          if (window.innerWidth < 960) {

            if (!breadcrumbs.hasClass('slick-initialized')) {
              breadcrumbs.slick({
                slidesToShow: 2,
                slidesToScroll: 1,
                variableWidth: true,
                arrows: false,
                infinite: false,
              });
            }

          } else{

            if (breadcrumbs.hasClass('slick-initialized')) {
              breadcrumbs.slick('unslick');
            }

          }
        }

      }

      // Mobile menu events.
      class MobileMenuEvents {

        // Selector mobile menu.
        mobileMenu() {
          return $('.mobile-menu');
        }

        // Selector body.
        body() {
          return $('body');
        }

        // Selector overlay for mobile menu.
        overlayMobileMenu() {
          return $('.overlay-mobile-menu');
        }

        // Selector header.
        header() {
          return $('.header__main');
        }

        // Selector product full bar.
        productFixedBar() {
          return $('.good-page__header');
        }

        // Event open mobile menu.
        openHeaderMenu () {

          this.body().addClass('fixed');
          this.mobileMenu().addClass('active');
          this.overlayMobileMenu().addClass('active');
          this.header().addClass('active');
          this.productFixedBar().addClass('active');

        }

        // Event close mobile menu.
        closeHeaderMenu () {

          let body = this.body();
          body.css('left', 0);

          setTimeout(function(){
            body.removeClass('fixed');
            body.css('left', '');
          }, 500);

          this.mobileMenu().removeClass('active');
          this.overlayMobileMenu().removeClass('active');
          this.header().removeClass('active');
          this.productFixedBar().removeClass('active');

        }

      }

      // Mobile filters events.
      class MobileFiltersEvents {

        // Open mobile filters.
        openFilter() {

          let body = $('body');
          let overlayMobileMenu = $('.overlay-mobile-menu');
          let header = $('.header__main');

          let block_filter = $('.catalog__aside');
          block_filter.addClass('active');
          $(body).addClass('fixed');
          $(body).addClass('fixed-filter');
          overlayMobileMenu.addClass('active');

          header.addClass('active');

        }

        // Close mobile filters.
        closeFilter() {

          let block_filter = $('.catalog__aside');
          let header = $('.header__main');

          block_filter.removeClass('active');
          header.removeClass('active');
        }

        // Change name title sorting for mobile.
        changeNameSortingMobile () {
          setTimeout(function() {
            $('#block-sortbyviewkatalogdisplaypage .catalog__sorting .select2-selection__rendered').text('Сортировка');
          }, 1000);
        }

        // Change name title sorting for default.
        changeNameSortingDefault () {
          let currentSortText = $('.catalog__sorting select').find(':selected').text();
          $('#block-sortbyviewkatalogdisplaypage .catalog__sorting .select2-selection__rendered').text(currentSortText);
        }

      }

      $('body', context).once('mobile-elements').each(function() {

        let mobileElements = new MobileElements();
        let mobileMenuEvents = new MobileMenuEvents();
        let mobileFiltersEvents = new MobileFiltersEvents();

        // Generated DOM elements for mobile.
        // Header menu.
        let headerMobileMenu = mobileElements.headerMobileMenu();
        $('.mobile-menu__items').append(headerMobileMenu);

        // Top header menu.
        let topHeaderMobileMenu = mobileElements.topHeaderMobileMenu();
        $('.mobile-menu__items-top').append(topHeaderMobileMenu);

        // Top header info.
        let topHeaderMobileInfo = mobileElements.topHeaderMobileInfo();
        $('.mobile-menu__items-info').append(topHeaderMobileInfo);

        // User mobile menu.
        let userMobileMenu = mobileElements.userMobileMenu();
        $('.bottom_menu').append(userMobileMenu);

        // Footer menu init.
        setTimeout(function() {
          if(window.innerWidth <= 768) {
            mobileElements.footerMobileMenu();
          }
        }, 1500);

        // Mobile menu events.
        // Event open (close) menu for icon.
        $('.header__main-row .toggle_menu, .bottom_menu_item.menu_catalog').on('click', function() {
          if (mobileMenuEvents.mobileMenu().hasClass('active')) {
            mobileMenuEvents.closeHeaderMenu();
          } else {
            mobileMenuEvents.openHeaderMenu();
          }

          return false;
        });

        // Close menu for event mobile overlay.
        mobileMenuEvents.overlayMobileMenu().on('click', function () {
          mobileMenuEvents.closeHeaderMenu();
          mobileFiltersEvents.closeFilter();
        });

        // Close menu for event "close" icon.
        $('.mobile-menu__close').on('click', function () {
          mobileMenuEvents.closeHeaderMenu();
        });

        // First level mobile menu event.
        $('.mobile-menu__item .mobile-menu__item-name').on('click', function () {

          if ($(this).parent('.mobile-menu__item').find('.mobile-menu__item-drops').hasClass('active')) {
            $(this).parent('.mobile-menu__item').removeClass('active');
            $(this).parent('.mobile-menu__item').find('.mobile-menu__item-drops').removeClass('active');
          } else {
            $(this).parent('.mobile-menu__item').addClass('active');
            $(this).parent('.mobile-menu__item').find('.mobile-menu__item-drops').addClass('active');
          }

          return false;

        });

        // Events for link catalog menu.
        $('.mobile-menu__item .mobile-menu__item-name a').on('click', function() {

          let current_item = $(this);
          let is_children = $(this).parents('.mobile-menu__item').find('.mobile-menu__item-drops').length;

          // If not children elements.
          if (is_children === 0) {
            window.location = $(this).attr('href');
            return false;
          }

          // If double click.
          if (current_item.hasClass('first_click')) {
            window.location = $(this).attr('href');
            return false;
          }

          // Fake simulation double click.
          current_item.addClass('first_click');
          setTimeout(function() {
            current_item.removeClass('first_click');
          }, 800);

        });

        // Two level mobile menu.
        $('.mobile-menu__item-drop .mobile-menu__item-name').on('click', function () {
          if ($(this).parent('.mobile-menu__item-drop').find('.mobile-menu__item-drop-items').hasClass('active')) {
            $(this).removeClass('active');
            $(this).parent('.mobile-menu__item-drop').find('.mobile-menu__item-drop-items').removeClass('active')
          } else {
            $(this).addClass('active');
            $(this).parent('.mobile-menu__item-drop').find('.mobile-menu__item-drop-items').addClass('active')
          }

          // return false;
        });

        // Filters events.
        $('.catalog__main').on('click', '.catalog__filter-icons', function() {
          let block_filter = $('.catalog__aside');
          if (block_filter.hasClass('active')) {
            mobileFiltersEvents.closeFilter();
          } else {
            mobileFiltersEvents.openFilter();
          }
        });

        // Event close filter block for icon.
        $('.mobile-filter__close').on('click', function() {
          mobileMenuEvents.closeHeaderMenu();
          mobileFiltersEvents.closeFilter();
        });
        // END Filters.

        // Change name sorting value.
        if(window.innerWidth <= 768) {
          mobileFiltersEvents.changeNameSortingMobile();
        }

        // Add class css for one stock for variation in catalog.
        $('.catalog__main .catalog__grid .catalog__grid-item').each(function(i, el) {
          let current_stock = $(el).find('.product-stock');
          if(current_stock.length === 1) {
            $(el).find('.product-teaser__stocks').addClass('not-button');
          }
        });

        // Add class css for one stock for variation in front.
        $('.spm-new__items .product-teaser').each(function(i, el) {
          let current_stock = $(el).find('.product-stock');
          if(current_stock.length === 1) {
            $(el).find('.product-teaser__stocks').addClass('not-button');
          }
        });

        // Breadcrumb catalog init.
        mobileElements.breadcrumbInit();

        // Resize window.
        $(window).resize(function(e) {

          mobileMenuEvents.closeHeaderMenu();
          if(window.innerWidth <= 768) {
            mobileElements.footerMobileMenu();
            mobileFiltersEvents.changeNameSortingMobile();
          } else {
            mobileFiltersEvents.changeNameSortingDefault();
          }

          // Breadcrumb catalog resize.
          mobileElements.breadcrumbInit();

        });

      });

      // Action add to cart, for bottom menu, for Product teaser (not variation).
      $('[is="add-to-cart"]').once().each(function () {
        $(this).click(function () {

          setTimeout(function() {
            let cartCount = $('.header__cart .header__count-value').text();
            if (cartCount > 0) {
              $('.bottom_menu_item.menu_cart .header__count').removeClass('hide');
              $('.bottom_menu_item.menu_cart .header__count-value').text(cartCount);
            }
          }, 1500);

        });
      });

    }
  };
})(jQuery, Drupal);
